function escapeText(value) {
  return String(value ?? "").replace(
    /[&<>"']/g,
    (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char],
  );
}

// Controls and actions are markup generated by the calling page.
export function renderPageHeading({
  title,
  eyebrow = "",
  count,
  countId = "",
  controls = "",
  actions = "",
  escapeHtml = escapeText,
}) {
  const counter = count == null ? "" : `<span class="heading-count"${countId ? ` id="${escapeHtml(countId)}"` : ""}>${escapeHtml(count)}</span>`;
  return `<header class="page-heading"><div class="page-eyebrow"${eyebrow ? "" : ' aria-hidden="true"'}>${escapeHtml(eyebrow)}</div><div class="page-heading-line"><h1 id="page-title" tabindex="-1">${escapeHtml(title)}${counter}</h1>${controls}</div>${actions ? `<div class="page-heading-actions">${actions}</div>` : ""}</header>`;
}
